(379730, 31390, 3554, '<td valign="top">This one feels a bit too cliche for me. It reminds me of movies where they try to hard to pull at your emotions. The general idea for the challenge was good.</td>', 'This one feels a bit too cliche for me. It reminds me of movies where they try to hard to pull at your emotions. The general idea for the challenge was good.', '2003-08-07 02:28:24.000000', NULL, 1),
(379733, 31779, 10275, '<td valign="top">Like the zoom effect. The point of interest could have been a bit sharper. Nice colour simplicity.</td>', 'Like the zoom effect. The point of interest could have been a bit sharper. Nice colour simplicity.', '2003-08-07 02:29:38.000000', NULL, 1),
