(382302, 32305, 2752, '<td valign="top">a perfect picture..father''s love shows and that cute baby''s eyes looking right at me says" I''m coming world and I will be ready"  Great composition and colors are lovely.(10)</td>', 'a perfect picture..father''s love shows and that cute baby''s eyes looking right at me says" I''m coming world and I will be ready"  Great composition and colors are lovely.(10)', '2003-08-09 00:11:54.000000', NULL, 1),
