(387448, 31947, 6870, '<td valign="top">Ahh, so true! Nice work--super composiiton and lovely tones for this mood. The trees seem a little oversharpened or pixelated somehow, but this is fine work!</td>', 'Ahh, so true! Nice work--super composiiton and lovely tones for this mood. The trees seem a little oversharpened or pixelated somehow, but this is fine work!', '2003-08-13 23:48:21.000000', NULL, 1),
(387449, 32259, 6870, '<td valign="top">Nice work. The figure in the lower left adds some humanity to what would otherwise be just an explosion. She seems blatantly pasted in (a bit sloppy), but this actually works for this image.</td>', 'Nice work. The figure in the lower left adds some humanity to what would otherwise be just an explosion. She seems blatantly pasted in (a bit sloppy), but this actually works for this image.', '2003-08-13 23:49:36.000000', NULL, 1),
(387451, 31485, 6870, '<td valign="top">Thank goodness SOMEONE will be around! Nice portrait! Lighting is exquisite and close composition works well.</td>', 'Thank goodness SOMEONE will be around! Nice portrait! Lighting is exquisite and close composition works well.', '2003-08-13 23:50:20.000000', NULL, 1),
(387452, 32352, 6870, '<td valign="top">Really swell job! I love it. Idea and composition are marvelous. Use of lighting to direct focus is well done,too. 10</td>', 'Really swell job! I love it. Idea and composition are marvelous. Use of lighting to direct focus is well done,too. 10', '2003-08-13 23:51:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(387454, 32268, 6870, '<td valign="top">This is subtle, very subtle, and for being creative with this challenge, kudos from me! Well composed and engaging shot.</td>', 'This is subtle, very subtle, and for being creative with this challenge, kudos from me! Well composed and engaging shot.', '2003-08-13 23:52:22.000000', NULL, 1),
(387455, 31870, 6870, '<td valign="top">So kids will have a sweet tooth even then? Some things never change! Nice work. Lots of color and a B/W face--and I''m not sure why. Lovely composition and exquisite clarity.</td>', 'So kids will have a sweet tooth even then? Some things never change! Nice work. Lots of color and a B/W face--and I''m not sure why. Lovely composition and exquisite clarity.', '2003-08-13 23:53:23.000000', NULL, 1),
(387456, 32362, 6870, '<td valign="top">He''s got my vote!</td>', 'He''s got my vote!', '2003-08-13 23:53:48.000000', NULL, 1),
(387457, 31483, 6870, '<td valign="top">Super colors. You''ve created a dark mood without using darkness all that much. Really intriguing work! 9</td>', 'Super colors. You''ve created a dark mood without using darkness all that much. Really intriguing work! 9', '2003-08-13 23:54:37.000000', NULL, 1),
(387458, 31536, 6870, '<td valign="top">Let''s hope this happens soon! Super work. A fine idea made excellent by your point of view from the side--adding power and hinting at other necessities. 10</td>', 'Let''s hope this happens soon! Super work. A fine idea made excellent by your point of view from the side--adding power and hinting at other necessities. 10', '2003-08-13 23:55:40.000000', NULL, 1),
(387459, 32333, 6870, '<td valign="top">Goofy. Two bad things combined together can''t make a good, can it? Just kidding, though I really don''t enjoy cats all that much. Fun, whimsical idea that is kept so by deliberately ''sloppy'' pasting.</td>', 'Goofy. Two bad things combined together can''t make a good, can it? Just kidding, though I really don''t enjoy cats all that much. Fun, whimsical idea that is kept so by deliberately ''sloppy'' pasting.', '2003-08-13 23:56:56.000000', NULL, 1),
